import { onFieldStats, type Stats } from '../engine/field';
import { Icon } from './ui';
import "./Nav.css"

const REPO = 'Aadarsh6/GLYPHA';
const REPO_URL = `https://github.com/${REPO}`;
const MIN_STARS_TO_SHOW = 1; // raise this if you would rather hide a small count

